function cellVal(p,r){return p.type==='created'?r.created:p.type==='updated'?r.updated:r.c[p.id]}
function cellText(p,r){if(isCalc(p.type)){const v=calc(p,r);return p.type==='formula'?Formula.show(v):String(v??'')}if(p.type==='relation'){const d=tdb(p);return relRows(p,r).map(x=>rowTitleIn(d,x)).join(', ')}
  const v=cellVal(p,r);if(v===undefined||v===null||v==='')return'';if(isSel(p.type))return optOf(p,v)?.n||'';if(isMul(p.type))return(v||[]).map(i=>optOf(p,i)?.n).filter(Boolean).join(', ');if(p.type==='check')return v?'✓':'';if(p.type==='file')return(v||[]).map(i=>blobs[i]?.name||'파일').join(', ');if(p.type==='created'||p.type==='updated')return new Date(v).toLocaleDateString('ko-KR');return String(v)}
const chip=o=>o?`<span class="opt" style="--c:${o.c}">${esc(o.n)}</span>`:'';
function chips(p,r){const v=r.c[p.id];if(isMul(p.type))return(v||[]).map(i=>chip(optOf(p,i))).join('');if(p.type==='relation'){const d=tdb(p);return relRows(p,r).map(x=>`<span class="opt rel" style="--c:#6478E8">↗ ${esc(rowTitleIn(d,x))}</span>`).join('')}return chip(optOf(p,v))}
function isDoneBy(p,r){const v=r.c[p.id];if(p.type==='check')return!!v;if(isSel(p.type))return/완료|다 읽음|엔딩|달성|계약|출시|실행|done/i.test(optOf(p,v)?.n||'');return!!v}
function isDone(r){const ck=D().props.filter(p=>p.type==='check'),sp=D().props.filter(p=>p.type==='status');if(ck.some(p=>r.c[p.id]))return true;if(sp.some(p=>isDoneBy(p,r)))return true;return false}
function dateAdd(s,u){const d=new Date(s+'T00:00');if(u==='매일')d.setDate(d.getDate()+1);if(u==='매주')d.setDate(d.getDate()+7);if(u==='매월')d.setMonth(d.getMonth()+1);if(u==='매년')d.setFullYear(d.getFullYear()+1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function checkRepeat(r){const rp=D().props.find(p=>p.type==='repeat');const o=rp&&optOf(rp,r.c[rp.id]);if(!o||r._rep||!isDone(r))return;const dp=D().props.find(p=>p.type==='date');if(!dp||!r.c[dp.id])return;r._rep=1;
  const n=JSON.parse(JSON.stringify(r));n.id=uid();delete n._rep;delete n.page;n.created=n.updated=now();n.c[dp.id]=dateAdd(r.c[dp.id],o.n);D().props.forEach(p=>{if(p.type==='check')n.c[p.id]=false;if(p.type==='status')n.c[p.id]=p.options[0]?.id||''});D().rows.push(n);toast(`반복 작업이에요 · 다음 일정(${n.c[dp.id]})을 만들었어요`)}
