const OPS={text:[['has','포함'],['nhas','포함 안 함'],['eq','같음'],['empty','비어 있음'],['nempty','비어 있지 않음']],number:[['eq','='],['ne','≠'],['gt','>'],['lt','<'],['ge','≥'],['le','≤'],['empty','비어 있음']],check:[['true','체크됨'],['false','체크 안 됨']],sel:[['is','같음'],['not','다름'],['empty','비어 있음'],['nempty','비어 있지 않음']],multi:[['has','포함'],['nhas','포함 안 함'],['empty','비어 있음']],date:[['today','오늘'],['week','7일 안'],['before','이전'],['after','이후'],['eq','같은 날'],['empty','비어 있음']]};
const opsFor=t=>t==='number'?OPS.number:t==='check'?OPS.check:isSel(t)?OPS.sel:isMul(t)?OPS.multi:['date','created','updated'].includes(t)?OPS.date:OPS.text;
function pass(f,r){const p=PR(f.p);if(!p)return true;const t=p.type;const v=isCalc(t)||t==='relation'||t==='file'?cellText(p,r):cellVal(p,r),emp=v===undefined||v===null||v===''||(Array.isArray(v)&&!v.length);if(f.op==='empty')return emp;if(f.op==='nempty')return!emp;
  if(t==='check')return f.op==='true'?!!v:!v;if(t==='number'){const a=+v,b=+f.v;if(emp)return false;return{eq:a===b,ne:a!==b,gt:a>b,lt:a<b,ge:a>=b,le:a<=b}[f.op]}
  if(isSel(t))return f.op==='is'?v===f.v:v!==f.v;if(isMul(t))return f.op==='has'?(v||[]).includes(f.v):!(v||[]).includes(f.v);
  if(['date','created','updated'].includes(t)){if(emp)return false;const d=typeof v==='number'?new Date(v):new Date(v+'T00:00');const s=new Date();s.setHours(0,0,0,0);d.setHours(0,0,0,0);if(f.op==='today')return+d===+s;if(f.op==='week')return Math.abs(d-s)<=7*864e5;const fv=f.v?new Date(f.v+'T00:00'):s;return f.op==='before'?d<fv:f.op==='after'?d>fv:+d===+fv}
  const tx=String(isCalc(t)||t==='relation'||t==='file'?v:cellText(p,r)).toLowerCase(),q=String(f.v||'').toLowerCase();return f.op==='has'?tx.includes(q):f.op==='nhas'?!tx.includes(q):tx===q}
