const SIMPLE=['text','number','select','multi','status','date','check','url','email','phone','person','repeat'];
function convertType(p,t){const old=p.type;if(old===t)return;const texts=D().rows.map(r=>cellText(p,r));p.type=t;
  if(isSel(t)||isMul(t)){if(t==='repeat')p.options=REP.map((n,i)=>opt(n,i));else if(!(isSel(old)||isMul(old))){const names=[...new Set(texts.flatMap(x=>isMul(t)?x.split(',').map(s=>s.trim()):[x]).filter(Boolean))];p.options=names.map((n,i)=>opt(n,i))}else p.options=p.options||[]}
  D().rows.forEach((r,i)=>{const tx=texts[i];if(isSel(t)){if(isMul(old))r.c[p.id]=(r.c[p.id]||[])[0]||'';else if(!isSel(old)||t==='repeat')r.c[p.id]=p.options.find(o=>o.n===tx)?.id||''}
    else if(isMul(t)){if(isSel(old))r.c[p.id]=r.c[p.id]?[r.c[p.id]]:[];else if(!isMul(old))r.c[p.id]=tx?tx.split(',').map(s=>p.options.find(o=>o.n===s.trim())?.id).filter(Boolean):[]}
    else if(t==='number'){const n=parseFloat(tx);r.c[p.id]=isNaN(n)?'':n}else if(t==='check')r.c[p.id]=!!tx&&tx!=='✗';else if(t==='date')r.c[p.id]=/^\d{4}-\d{2}-\d{2}/.test(tx)?tx.slice(0,10):'';else r.c[p.id]=tx});
  if(!(isSel(t)||isMul(t)))delete p.options;touch(pg);render()}
